[[[
const d = variables.d;
  const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const decimal = (n,digits=0) => Number(n).toLocaleString('en-GB',{maximumFractionDigits:digits});
  const positive = n => typeof n === 'number' && Number.isFinite(n) && n > 0;
  const duration = minutes => {
    if (!positive(minutes)) return '';
    const m = Math.max(1,Math.round(minutes));
    return m < 60 ? `${m} min` : `${Math.floor(m / 60)} h ${m % 60} min`;
  };
  const date = (value,options) => Number.isFinite(Date.parse(value)) ? new Date(value).toLocaleString('en-GB',options) : '';
  const image = (...candidates) => candidates.find(p => typeof p === 'string' && /^\/snapmaker_u1_card\/thumbs\//.test(p));
  const metric = (label,value) => value ? `<div><dt>${label}</dt><dd>${esc(value)}</dd></div>` : '';
  const result = {complete:'Completed',completed:'Completed',cancelled:'Cancelled',canceled:'Cancelled',error:'Error',failed:'Error',aborted:'Cancelled'};
  const err = d.known && d.status === 'error';
  const activeJob = d.running || err;
  const last = d.known && !activeJob ? d.last : null;
  const thumb = activeJob ? image(d.model?.thumb) : last ? image(last.thumb,d.lastModel?.thumb,last.photo) : undefined;
  const pct = d.running && d.progress !== null ? Math.round(Math.max(0,Math.min(100,d.progress))) : null;
  const short = v => v.replace(/\.(gcode|3mf)$/i,'').replace(/[_+]+/g,' ');
  const filename = activeJob ? short(d.filename) : last ? short(last.name || last.file) : '';
  const heading = activeJob ? 'Print job' : d.known ? 'Last print' : 'Print job';
  const chip = activeJob ? d.label : last ? result[last.result] : '';
  const finish = date(d.eta,{hour:'2-digit',minute:'2-digit'});
  const ended = date(last?.ended,{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
  const filament = positive(last?.filament_used) ? `${decimal(last.filament_used / 1000,2)} m` : '';
  const layer = d.layer || d.layers ? `${d.layer ?? 'â€”'} / ${d.layers ?? 'â€”'}` : '';
  const metrics = d.running
    ? metric('Layer',layer)+metric('ETA',finish)+metric('Remaining',duration(d.remaining))+metric('Elapsed',duration(d.elapsed))
    : last ? metric('Duration',duration(last.duration / 60))+metric('Filament',filament) : '';
  const statusText = err ? d.reason || 'The printer reported an error.'
    : d.status === 'paused' && d.running ? d.reason || 'The print is waiting to resume.'
    : !d.online ? 'Printer disconnected.'
    : !d.known ? 'Print status is currently unknown.'
    : !activeJob && !last ? 'No print has been recorded yet.' : '';
  const tone = activeJob ? d.tone : last && ['complete','completed'].includes(last.result) ? 'ok' : 'neutral';
  return `<style>
    .u1-job-h{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:6px 8px;margin-bottom:12px}
    .u1-job-h b{font-size:17px;font-weight:720}
    .u1-job-badge{font-size:11px;font-weight:650;border-radius:99px;padding:4px 8px;background:color-mix(in srgb,var(--secondary-text-color) 12%,transparent);color:var(--secondary-text-color)}
    .u1-job-badge[data-tone=ok]{color:#a1d5a8;background:#75b48320}
    .u1-job-badge[data-tone=hot],.u1-job-badge[data-tone=error]{color:#ffab98;background:#ff634724}
    .u1-job-badge[data-tone=warn]{color:#f3be73;background:#f3be7323}
    .u1-job-main{display:grid;grid-template-columns:minmax(0,1fr);gap:11px;align-items:center}
    .u1-model{display:block;box-sizing:border-box;width:100%;height:clamp(105px,12vw,165px);object-fit:contain;border-radius:11px;padding:6px;background:radial-gradient(ellipse at 50% 55%,#46423f,#242327 76%)}
    .u1-filename{font-weight:720;font-size:16px;line-height:1.25;overflow-wrap:anywhere}
    .u1-muted{color:var(--secondary-text-color);font-size:12px;line-height:1.4}
    .u1-pct{font-size:clamp(26px,3.2vw,39px);font-weight:760;letter-spacing:-.04em;line-height:1;color:#ff7961;margin:0 0 7px}
    .u1-pct small{font-size:.49em;letter-spacing:0}
    .u1-track{height:6px;border-radius:99px;background:var(--divider-color);overflow:hidden;margin-bottom:12px}
    .u1-track i{display:block;height:100%;background:#ff6347;border-radius:inherit}
    .u1-job-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 8px;margin:12px 0 0;padding-top:11px;border-top:1px solid var(--divider-color)}
    .u1-job-metrics dt{color:var(--secondary-text-color);font-size:12px}.u1-job-metrics dd{margin:3px 0 0;font-weight:710;font-size:15px}
    @media(max-width:560px){.u1-job-main.has-model{grid-template-columns:86px minmax(0,1fr)}.u1-model{height:82px}.u1-filename{font-size:14px}.u1-job-h{margin-bottom:9px}}
    </style><div class="u1-job-h"><b>${heading}</b>${chip ? `<span class="u1-job-badge" data-tone="${tone}">${chip}</span>` : ''}</div>
    ${pct === null ? '' : `<div class="u1-pct">${pct}<small> %</small></div><div class="u1-track" role="progressbar" aria-label="Print progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><i style="width:${pct}%"></i></div>`}
    ${(thumb || filename) ? `<div class="u1-job-main ${thumb ? 'has-model' : ''}">${thumb ? `<img class="u1-model" src="${esc(thumb)}" alt="${thumb===last?.photo && thumb!==last?.thumb ? 'Photo of the last print' : 'Model thumbnail'}">` : ''}<div><div class="u1-filename">${esc(filename)}</div>${ended ? `<div class="u1-muted">${esc(ended)}</div>` : ''}</div></div>` : ''}
    ${statusText ? `<div class="u1-muted" style="margin-top:${filename ? 8 : 0}px">${esc(statusText)}</div>` : ''}
    ${metrics ? `<dl class="u1-job-metrics">${metrics}</dl>` : ''}`;
]]]

