card_mod.style:
ha-card { border-radius: 14px; box-shadow: none; }
.head { display: none !important; }
.head-card[data-active="1"] { border-color: transparent; background: var(--u1-panel-high); }
.heads { grid-template-columns: repeat(auto-fit, minmax(min(100%, 155px), 1fr)); }
.head-card[data-active="1"] .spool > circle[stroke-width="2.5"] { display: none; }
{% set live = is_state('binary_sensor.snapmaker_u1_card_live_verbindung', 'on') and has_value('sensor.snapmaker_u1_card_druckerwerte') and has_value('sensor.snapmaker_u1_card_druckstatus') %}
{% set raw = state_attr('sensor.snapmaker_u1_card_filamente', 'head_states') %}
{% set positions = raw if live and raw is sequence and raw is not string and raw is not mapping else [] %}
{% set mounted = positions | select('eq', 'active') | list | count %}
{% set selected = state_attr('sensor.snapmaker_u1_card_filamente', 'active_head') if live else none %}
{% set motion = state_attr('sensor.snapmaker_u1_card_druckerwerte', 'values') or {} %}
{% set slots = state_attr('sensor.snapmaker_u1_card_filamente', 'slots') or [] %}
{% for i in range(4) %}
  {% set inlet = slots | selectattr('index', 'eq', i) | first | default({}) %}
  {% set position = positions[i] if i < positions | count else none %}
  {% set label = 'Docked' if position == 'parked' else 'Mounted' if position == 'active' and mounted == 1 else 'Position unknown' %}
  .head-card[data-head="{{ i }}"] .head-name::after {
    content: "T{{ i }} Â· {{ label }}{% if selected is integer and selected == i %} Â· Firmware selection{% endif %}{% if live and motion.get('e' ~ i ~ '_filament') == 'off' and inlet.get('loaded') is sameas true %} Â· At feeder only{% endif %}";
    display: block;
    margin: 3px 0 2px;
    white-space: normal;
    color: {{ '#ff8069' if position == 'active' and mounted == 1 else 'var(--secondary-text-color)' }};
    font-size: 11px;
    font-weight: 550;
    line-height: 1.28;
  }
{% endfor %}
.head-card-top { align-items: flex-start; }
@media (max-width: 600px) {
  .heads { grid-template-columns: repeat(auto-fit, minmax(min(100%, 133px), 1fr)); gap: 7px; }
  .head-card { padding: 8px; }
  .head-card-top { gap: 5px; }
  .head-card .spool { width: 27px; height: 27px; }
}
@media (min-width: 601px) and (max-width: 900px) {
  .heads { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
ha-card { background: transparent; border: 0; padding: 0; }
.panel:has(> .heads) { margin: 0; }
.panel > .panel-head .panel-title { font-size:16px; font-weight:700; line-height:1.25; color:var(--primary-text-color); }

custom_fields.state:
[[[
const online = states['binary_sensor.snapmaker_u1_card_live_verbindung']?.state === 'on';
const st = states['sensor.snapmaker_u1_card_druckstatus']?.state;
const busy = states['script.u1_fusion_v2_control']?.state === 'on';
const ready = states['sensor.snapmaker_u1_card_druckerwerte']?.state === 'ready';
const value = states['sensor.snapmaker_u1_card_druckerwerte']?.attributes?.values ?? {};
const xyz = ['x','y','z'].map(a => {
  const n = value['toolhead_position_' + a];
  const shown = online && n !== null && n !== undefined && String(n).trim() !== '' && Number.isFinite(Number(n));
  return a.toUpperCase() + ' ' + (shown ? Number(n).toFixed(1) : 'â€”');
}).join(' Â· ');
const needsHome = online && (states['sensor.snapmaker_u1_card_druckerwerte']?.attributes?.values?.idle_timeout_state === 'Idle');
const result = states['input_text.u1_fusion_v2_action_status']?.state;
const safe = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hint = busy ? 'Action in progress' : !online ? 'Offline' : ['printing','paused'].includes(st) ? 'Locked while printing' : !ready || !['standby','ready','complete','cancelled'].includes(st) ? 'Printer is not ready' : needsHome ? 'Homing required' : 'Idle';
const detail = needsHome ? 'Motors off after idle timeout' : xyz + ' mm';
const messages = new Map([["Unbekannte U1-Aktion.","Unknown U1 action."],["U1-Zustand gelesen.","U1 status read."],["Der aktuelle Druckerzustand ist nicht erreichbar.","Current printer status is unavailable."],["U1 gesperrt. Der Drucker muss online, fehlerfrei und im Leerlauf sein.","U1 controls are locked. The printer must be online, idle and free of errors."],["Zuerst â€žAchsen referenzierenâ€œ. Die Achsen sind nicht referenziert.","Home the axes first."],["U1-Fahrt gesperrt. Schritt, Koordinaten oder Softlimit ungÃ¼ltig.","Move blocked. The step, coordinates or software limit is invalid."],["U1-Filamentaktion gesperrt. Feeder, Filamentzustand oder Sensor des gewÃ¤hlten Kopfes prÃ¼fen.","Filament action blocked. Check the selected tool's feeder, filament and sensor."],["Bett zuerst auf Mitte oder Unten fahren, damit der Kopf genug Abstand hat.","Move the bed to Center or Bottom first to give the tool enough clearance."],["U1-Preset gesperrt. FÃ¼r diese Position muss genau ein Druckkopf am Schlitten sein.","Move blocked. This position requires exactly one tool mounted on the carriage."],["U1-Preset gesperrt. Ziel, Achsgrenzen oder aktuelle Position ungÃ¼ltig.","Move blocked. The target, axis limits or current position is invalid."],["U1 steht bereits am gewÃ¤hlten Ziel.","The U1 is already at the selected position."],["U1-Kopfaufnahme gesperrt. Werkzeugindex oder Dock-/Schlittenposition ungÃ¼ltig.","Tool pickup blocked. The tool index, dock or carriage position is invalid."],["Der gewÃ¤hlte Druckkopf ist bereits am Schlitten.","The selected tool is already mounted."],["U1-Parken gesperrt. Dock- oder Schlittenposition ist unklar.","Docking blocked. Dock or carriage position is unknown."],["Alle DruckkÃ¶pfe sind bereits im Dock.","All tools are already docked."],["U1-Zustand hat sich geÃ¤ndert. Aktion gesperrt.","Printer status changed. Action blocked."],["U1-Befehl fehlgeschlagen oder ZeitÃ¼berschreitung. Vor Wiederholung Druckerzustand und G-Code-Konsole prÃ¼fen.","The command failed or timed out. Check the printer and G-code console before retrying."],["U1 hat den erwarteten Endzustand nicht bestÃ¤tigt. Druckerzustand vor einer Wiederholung prÃ¼fen.","The U1 did not confirm the expected result. Check the printer before retrying."],["Achsen referenziert.","Axes homed."],["Zielposition erreicht.","Target position reached."],["Feinbewegung abgeschlossen.","Fine move completed."],["Druckkopf am Schlitten bestÃ¤tigt.","Tool confirmed on the carriage."],["Druckkopf im Dock bestÃ¤tigt.","Tool confirmed in the dock."],["Filament geladen.","Filament loaded."],["Filament entladen.","Filament unloaded."],["Aktion abgeschlossen.","Action complete."]]);
const note = !busy && result && !['Bereit','unknown','unavailable'].includes(result) && !(needsHome && (result.startsWith('Zuerst') || result === 'Achsen referenziert.')) ? '<br>' + safe(messages.get(result) || result) : '';
return '<span style="font-size:11px;color:var(--secondary-text-color)"><strong style="color:' + (needsHome ? '#ff8069' : 'var(--primary-text-color)') + '">' + hint + '</strong><br>' + detail + note + '</span>';
]]]

